import java.util.*;

class Solution {
    public int diameter(TreeNode root) {
        int[] answer = new int[1];
        dfs(root, answer);
        return answer[0];
    }

    private int dfs(TreeNode node, int[] answer) {
        if (node == null) {
            return 0;
        }
        int left = dfs(node.left, answer);
        int right = dfs(node.right, answer);
        answer[0] = Math.max(answer[0], left + right);
        return (left > right ? left : right) + 1;
    }
}
